PROGRAM A03_LINA
VAR
    s1steg  : INT := 0;
    s2steg  : INT := 0;
    tmr1    : TON;
    tmr2    : TON;
    tpAck   : TP;
    xSlapp  : BOOL := FALSE;
    xTaEmot : BOOL := FALSE;
    xDrift  : BOOL := FALSE;
END_VAR

(* Linans takt satts av den langsammaste stationen. Station 1 arbetar 26,0 s
   och station 2 arbetar 31,0 s, sa takten ar 31,0 s och station 1 star och
   vantar 5,0 s per enhet. Den vantan ar inte ett fel som ska optimeras bort
   i styrningen: den ar forreglingen framat, och tas den bort trycks en enhet
   in i en station som annu arbetar. *)

(* EMG_OK ar sakerhetskretsens egen OK-kontakt och lases bara. Den gar hog
   forst nar kretsen ar manuellt aterstalld i sakerhetsdelen, sa den har
   logiken aterstaller aldrig sjalv ett nodstopp; den ar forreglad AV den. *)
xDrift := EMG_OK;

tmr1(IN := ST250_STA_BUSY, PT := T#26s);
tmr2(IN := ST260_STA_BUSY, PT := T#31s);

(* Kvittensen ar en puls och inte en niva. Den ska vara langre an mottagarens
   avsokning sa att den aldrig kan missas, och kortare an takten sa att tva
   enheter aldrig kan dela pa samma kvittens. *)
tpAck(IN := xTaEmot, PT := T#500ms);

IF NOT xDrift THEN
    (* Ett brutet nodstopp tar bort varje kommenderat don i samma scan.
       Stegen behalls: enheterna star kvar dar de star, och klarsignalerna
       med dem. Arbetstiden borjar om, for en halvt utford operation ar inte
       halvt klar. *)
    xSlapp := FALSE;
ELSE
    (* ---------------- station 1 ---------------- *)
    CASE s1steg OF
        0:
            (* En ny enhet far inte borja arbetas pa sa lange foregaende
               enhets klarsignal star kvar. Annars arver den nya enheten
               beskedet. *)
            IF ST250_PRT_PRS AND NOT ST250_STA_DONE THEN
                s1steg := 1;
            END_IF;
        1:
            IF tmr1.Q THEN
                ST250_STA_DONE := TRUE;
                s1steg := 2;
            END_IF;
        2:
            (* Forreglingen framat: grinden far oppna forst nar station 2
               sagt sig tom och klar, och bara for en enhet som star har. *)
            IF ST250_STA_DONE AND ST260_STA_RDY AND ST250_PRT_PRS THEN
                xSlapp := TRUE;
                s1steg := 3;
            END_IF;
        3:
            IF NOT ST260_STA_RDY THEN
                (* Station 2 blev upptagen medan grinden stod oppen. Stang
                   den igen och hall enheten kvar. *)
                xSlapp := FALSE;
                s1steg := 2;
            ELSIF NOT ST250_PRT_PRS THEN
                xSlapp := FALSE;
                s1steg := 4;
            END_IF;
        4:
            (* Handskakningen nollstalls at det har hallet: klarsignalen star
               kvar tills station 2 kvitterat mottagandet. Forst da far
               stationen borja pa en ny enhet, och samma klarsignal kan
               aldrig slappa tva enheter. *)
            IF ST260_ACK_RST THEN
                ST250_STA_DONE := FALSE;
                s1steg := 0;
            END_IF;
    ELSE
        s1steg := 0;
    END_CASE;

    (* ---------------- station 2 ---------------- *)
    CASE s2steg OF
        0:
            (* Forreglingen bakat: narvaron ensam ar inget startvillkor. En
               enhet kan sta i stationen utan att station 1 blivit klar med
               den, och da ar den halvfardig. *)
            IF ST260_PRT_PRS AND ST250_STA_DONE THEN
                xTaEmot := TRUE;
                s2steg := 1;
            END_IF;
        1:
            IF NOT ST250_STA_DONE THEN
                xTaEmot := FALSE;
            END_IF;
            IF tmr2.Q THEN
                ST260_STA_DONE := TRUE;
                s2steg := 2;
            END_IF;
        2:
            IF NOT ST260_PRT_PRS THEN
                ST260_STA_DONE := FALSE;
                s2steg := 0;
            END_IF;
    ELSE
        s2steg := 0;
    END_CASE;
END_IF;

ST250_STA_BUSY := (s1steg = 1) AND xDrift;
ST250_REL_OPEN := xSlapp AND ST250_STA_DONE AND ST260_STA_RDY
                  AND ST250_PRT_PRS AND xDrift;
ST260_STA_BUSY := (s2steg = 1) AND xDrift;
ST260_ACK_RST := tpAck.Q;
END_PROGRAM

